def divideArray(nums):
    # Create a fixed-size array for counts (since 1 ≤ nums[i] ≤ 500)
    count = [0] * 501

    # Count frequency of each value
    for num in nums:
        count[num] += 1

    # If any number has odd count, pairing is impossible
    for c in count:
        if c % 2 != 0:
            return False

    return True
